template <class T>
class my_allocator
{
public:
  T *allocate(size_t);
  void deallocate(T *, size_t);
};

template <class T>
inline void construct(T *p, const T& value)
{
  new (p) T(value);
}

template <class T>
inline void destroy(T *first, T *last)
{
  while (first != last)
  {
    first->~T();
    ++first;
  }
}

template <class T>
inline T *copy_backward(T *first, T *last, T *result)
{
  while (last != first)
    *--result = *--last;
  return result;
}

template <class T>
inline T *uninitialized_copy(T *first, T *last, T *result)
{
  while (first != last)
  {
    construct(result, *first);
    ++first;
    ++result;
  }
  return result;
}

